window.products.push({"id":799157,"name":"EVO Sustainable Goods 16 oz. Bowl Set, Red","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71ycFpTwNsL._AC_SL1500_.jpg","description":"These wpc (wood plastic composite) bowls blend versatility with sustainability. Perfectly suited for snacks, soups, and cereal, these fun and durable bowls will be a staple around the kitchen. As always, these BPA free products are dishwasher and microwave safe.","images":["https://m.media-amazon.com/images/I/71ycFpTwNsL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"EVO Sustainable Goods","source_asin":"B01N4NUB27","category_path":"Home & Kitchen"},"sku":"BM-799157","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01N4NUB27","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01N4NUB27","price_pending":true,"merchant_ready":false});
